CREATE TABLE IF NOT EXISTS appointments (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, customer_id TEXT NOT NULL, service_id TEXT NOT NULL, professional_id TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, duration_minutes INTEGER NOT NULL, base_price_cents INTEGER, discount_cents INTEGER, final_price_cents INTEGER, deposit_cents INTEGER, origin TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (tenant_id) REFERENCES tenants(id), FOREIGN KEY (customer_id) REFERENCES customers(id), FOREIGN KEY (service_id) REFERENCES services(id), FOREIGN KEY (professional_id) REFERENCES professionals(id));
CREATE INDEX IF NOT EXISTS idx_appointments_professional_time ON appointments(tenant_id, professional_id, starts_at, ends_at);
CREATE INDEX IF NOT EXISTS idx_appointments_tenant_time ON appointments(tenant_id, starts_at);
CREATE INDEX IF NOT EXISTS idx_appointments_customer_time ON appointments(tenant_id, customer_id, starts_at);
